#!/bin/bash
#==============================================================================
# VulnScan - Advanced Vulnerability Scanner for Bug Bounty Hunting
# Integrates with LinPEAS for system enumeration + CVE database lookups
# FOR AUTHORIZED PENETRATION TESTING ONLY
#==============================================================================

VERSION="1.0.0"
SELF_PATH="$(readlink -f "$0" 2>/dev/null || echo "$0")"
SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
TIMESTAMP=$(date +%Y%m%d_%H%M%S)
OUTPUT_DIR="${SCRIPT_DIR}/vulnscan_results_${TIMESTAMP}"
LINPEAS_OUTPUT=""
LINPEAS_PATH="/tmp/.vulnscan_linpeas_${TIMESTAMP}.sh"
CVSS_THRESHOLD="${CVSS_THRESHOLD:-5.0}"
MAX_CVE_RESULTS=10
REPORT_TXT=""
REPORT_JSON=""
TOTAL_CRITICAL=0; TOTAL_HIGH=0; TOTAL_MEDIUM=0; TOTAL_LOW=0; TOTAL_INFO=0

# Cleanup temp files on exit
cleanup() { rm -f "$LINPEAS_PATH" 2>/dev/null; }
trap cleanup EXIT INT TERM

# Colors
R='\033[1;31m'; G='\033[1;32m'; Y='\033[1;33m'; B='\033[1;34m'
M='\033[1;35m'; C='\033[1;36m'; W='\033[1;37m'; D='\033[0;90m'; NC='\033[0m'

banner() {
cat << 'EOF'

 ██╗   ██╗██╗   ██╗██╗     ███╗   ██╗███████╗ ██████╗ █████╗ ███╗   ██╗
 ██║   ██║██║   ██║██║     ████╗  ██║██╔════╝██╔════╝██╔══██╗████╗  ██║
 ██║   ██║██║   ██║██║     ██╔██╗ ██║███████╗██║     ███████║██╔██╗ ██║
 ╚██╗ ██╔╝██║   ██║██║     ██║╚██╗██║╚════██║██║     ██╔══██║██║╚██╗██║
  ╚████╔╝ ╚██████╔╝███████╗██║ ╚████║███████║╚██████╗██║  ██║██║ ╚████║
   ╚═══╝   ╚═════╝ ╚══════╝╚═╝  ╚═══╝╚══════╝ ╚═════╝╚═╝  ╚═╝╚═╝  ╚═══╝

EOF
echo -e "${C}  VulnScan v${VERSION} - Advanced Vulnerability Scanner${NC}"
echo -e "${D}  LinPEAS Embedded + CVE Database Lookup${NC}"
echo -e "${Y}  For Authorized Bug Bounty & Penetration Testing Only${NC}"
echo ""
}

log()  { echo -e "${G}[+]${NC} $1"; }
warn() { echo -e "${Y}[!]${NC} $1"; }
err()  { echo -e "${R}[-]${NC} $1"; }
info() { echo -e "${B}[*]${NC} $1"; }
section() { echo -e "\n${M}═══════════════════════════════════════════════════════${NC}"; echo -e "${M}  $1${NC}"; echo -e "${M}═══════════════════════════════════════════════════════${NC}"; }

# Append to text report
rpt() { echo "$1" >> "$REPORT_TXT"; }

#==============================================================================
# EXTRACT EMBEDDED LINPEAS (base64 payload at end of this script)
#==============================================================================
extract_linpeas() {
    info "Extracting embedded LinPEAS from payload..."
    local marker="__LINPEAS_PAYLOAD_BELOW__"
    local payload_line=$(grep -n "^${marker}$" "$SELF_PATH" | tail -1 | cut -d: -f1)
    if [[ -z "$payload_line" ]] || [[ "$payload_line" -eq 0 ]]; then
        err "Embedded LinPEAS payload not found in script!"
        err "This script requires the base64 payload appended after __LINPEAS_PAYLOAD_BELOW__ marker."
        exit 1
    fi
    tail -n +$((payload_line + 1)) "$SELF_PATH" | base64 -d > "$LINPEAS_PATH" 2>/dev/null
    if [[ -s "$LINPEAS_PATH" ]]; then
        chmod +x "$LINPEAS_PATH"
        log "LinPEAS extracted ($(du -h "$LINPEAS_PATH" | cut -f1)) ✓"
    else
        err "Failed to extract LinPEAS payload. File may be corrupted."
        exit 1
    fi
}

#==============================================================================
# DISCLAIMER & DEPENDENCY CHECKS
#==============================================================================
disclaimer() {
    echo -e "${R}╔══════════════════════════════════════════════════════════╗${NC}"
    echo -e "${R}║  LEGAL DISCLAIMER                                        ║${NC}"
    echo -e "${R}║  This tool is for AUTHORIZED penetration testing and      ║${NC}"
    echo -e "${R}║  bug bounty programs ONLY. Unauthorized access to         ║${NC}"
    echo -e "${R}║  computer systems is illegal. The author assumes NO       ║${NC}"
    echo -e "${R}║  liability for misuse. You must have explicit written     ║${NC}"
    echo -e "${R}║  permission to test the target system.                    ║${NC}"
    echo -e "${R}╚══════════════════════════════════════════════════════════╝${NC}"
    echo ""
    read -p "Do you have authorization to test this system? (yes/no): " consent
    if [[ "$consent" != "yes" ]]; then
        err "Authorization not confirmed. Exiting."
        exit 1
    fi
}

check_deps() {
    section "Checking Dependencies"

    # Core tools that are almost always present
    for cmd in curl sed awk grep base64; do
        if command -v "$cmd" &>/dev/null; then
            log "$cmd found ✓"
        else
            err "$cmd not found! This is a core system tool — cannot proceed."
            exit 1
        fi
    done

    # jq — download portable binary if not installed (no sudo needed)
    if ! command -v jq &>/dev/null; then
        warn "jq not found — downloading portable binary..."
        local arch=$(uname -m)
        local jq_url=""
        case "$arch" in
            x86_64|amd64)  jq_url="https://github.com/jqlang/jq/releases/download/jq-1.7.1/jq-linux-amd64" ;;
            aarch64|arm64) jq_url="https://github.com/jqlang/jq/releases/download/jq-1.7.1/jq-linux-arm64" ;;
            armv7l|armhf)  jq_url="https://github.com/jqlang/jq/releases/download/jq-1.7.1/jq-linux-armhf" ;;
            i686|i386)     jq_url="https://github.com/jqlang/jq/releases/download/jq-1.7.1/jq-linux-i386" ;;
            *)             jq_url="https://github.com/jqlang/jq/releases/download/jq-1.7.1/jq-linux-amd64" ;;
        esac
        if curl -sL --max-time 30 "$jq_url" -o /tmp/jq 2>/dev/null && [[ -s /tmp/jq ]]; then
            chmod +x /tmp/jq
            export PATH="/tmp:$PATH"
            log "jq downloaded to /tmp/jq ✓"
        else
            err "Failed to download jq. Install manually: apt install jq / yum install jq"
            exit 1
        fi
    else
        log "jq found ✓"
    fi

    # bc — optional, use awk fallback if missing
    if command -v bc &>/dev/null; then
        log "bc found ✓"
    else
        info "bc not found — using awk for math (OK)"
    fi

    mkdir -p "$OUTPUT_DIR"
    REPORT_TXT="${OUTPUT_DIR}/vulnscan_report.txt"
    REPORT_JSON="${OUTPUT_DIR}/vulnscan_report.json"
    LINPEAS_OUTPUT="${OUTPUT_DIR}/linpeas_raw.txt"
    log "Output directory: ${OUTPUT_DIR}"

    # Extract embedded LinPEAS
    extract_linpeas
}

#==============================================================================
# LINPEAS EXECUTION (extracted from embedded payload)
#==============================================================================
run_linpeas() {
    section "Running LinPEAS Enumeration"
    info "Running in fast mode (stealth)..."
    
    # Check if timeout command exists
    local has_timeout=0
    command -v timeout &>/dev/null && has_timeout=1

    # Start LinPEAS in background so we can monitor progress
    if [[ $has_timeout -eq 1 ]]; then
        timeout 300 "$LINPEAS_PATH" -s -N > "$LINPEAS_OUTPUT" 2>/dev/null &
    else
        "$LINPEAS_PATH" -s -N > "$LINPEAS_OUTPUT" 2>/dev/null &
    fi
    
    local lp_pid=$!
    local start_time=$(date +%s)
    local last_lines=0
    
    # Monitor progress
    while kill -0 $lp_pid 2>/dev/null; do
        local curr_time=$(date +%s)
        local elapsed=$((curr_time - start_time))
        
        # Every 10 seconds, show progress
        if [[ $((elapsed % 10)) -eq 0 ]]; then
            local current_lines=$(wc -l < "$LINPEAS_OUTPUT" 2>/dev/null || echo 0)
            local last_activity=$(tail -n 1 "$LINPEAS_OUTPUT" 2>/dev/null | grep -oP '\[\*\] [^\[]*' | head -1 | cut -c 1-50)
            echo -ne "${B}[*]${NC} Progress: $elapsed s | Lines: $current_lines | Active: ${last_activity:-Scanning...}          \r"
        fi
        
        # Fail-safe local timeout (10 minutes) if timeout command failed or missing
        if [[ $elapsed -gt 600 ]]; then
            warn "LinPEAS exceeded 10 minute local limit. Killing..."
            kill -9 $lp_pid 2>/dev/null
            break
        fi
        sleep 2
    done
    echo "" # New line after the \r progress

    wait $lp_pid 2>/dev/null
    local exit_code=$?
    
    if [[ $exit_code -eq 124 ]]; then
        warn "LinPEAS timed out (partial results captured)"
    fi
    
    log "LinPEAS enumeration complete ✓"
    rm -f "$LINPEAS_PATH" 2>/dev/null
}

#==============================================================================
# SYSTEM INFO PARSER
#==============================================================================
declare -A SYS_INFO
PACKAGES_LIST=""
SUID_BINS=""
SERVICES_LIST=""
OPEN_PORTS=""
SUDO_INFO=""
CRON_JOBS=""

parse_system_info() {
    section "Parsing System Information"

    # Kernel
    SYS_INFO[kernel]=$(uname -r 2>/dev/null || grep -m1 "Linux version" "$LINPEAS_OUTPUT" | grep -oP '\d+\.\d+\.\d+[^\s]*')
    SYS_INFO[kernel_full]=$(uname -a 2>/dev/null)
    log "Kernel: ${SYS_INFO[kernel]}"

    # OS/Distribution
    if [[ -f /etc/os-release ]]; then
        SYS_INFO[distro]=$(. /etc/os-release && echo "$PRETTY_NAME")
        SYS_INFO[distro_id]=$(. /etc/os-release && echo "$ID")
        SYS_INFO[distro_ver]=$(. /etc/os-release && echo "$VERSION_ID")
    else
        SYS_INFO[distro]=$(grep -m1 "PRETTY_NAME\|Distributor ID" "$LINPEAS_OUTPUT" | head -1)
    fi
    log "OS: ${SYS_INFO[distro]}"

    # Hostname & User
    SYS_INFO[hostname]=$(hostname 2>/dev/null)
    SYS_INFO[user]=$(whoami 2>/dev/null)
    SYS_INFO[id]=$(id 2>/dev/null)
    log "User: ${SYS_INFO[user]}@${SYS_INFO[hostname]}"

    # Installed packages (top 100 for CVE scanning)
    info "Extracting installed packages..."
    if command -v dpkg &>/dev/null; then
        PACKAGES_LIST=$(dpkg -l 2>/dev/null | awk '/^ii/{print $2"="$3}' | head -100)
    elif command -v rpm &>/dev/null; then
        PACKAGES_LIST=$(rpm -qa --queryformat '%{NAME}=%{VERSION}\n' 2>/dev/null | head -100)
    elif command -v apk &>/dev/null; then
        PACKAGES_LIST=$(apk list --installed 2>/dev/null | sed 's/ .*//;s/-\([0-9]\)/=\1/' | head -100)
    fi
    local pkg_count=$(echo "$PACKAGES_LIST" | grep -c '.' 2>/dev/null)
    log "Found ${pkg_count} packages for CVE scanning"

    # SUID binaries - Optimized to avoid hang
    info "Extracting SUID/SGID binaries..."
    
    # Try parsing from LinPEAS output first (most efficient)
    SUID_BINS=$(grep -A100 "Interesting SUID files" "$LINPEAS_OUTPUT" | grep "^/" | head -50)
    
    if [[ -z "$SUID_BINS" ]]; then
        # Fallback 1: Fast search in common binary paths only
        local common_paths="/usr/bin /usr/sbin /bin /sbin /usr/local/bin /usr/local/sbin"
        SUID_BINS=$(find $common_paths -perm -4000 -type f 2>/dev/null | head -50)
    fi

    if [[ -z "$SUID_BINS" ]]; then
        # Fallback 2: Last resort, restricted find on / with timeout
        info "Trying restricted find (30s limit)..."
        SUID_BINS=$(timeout 30 find / -xdev -perm -4000 -type f 2>/dev/null | head -50)
    fi
    
    local suid_count=$(echo "$SUID_BINS" | grep -v "^$" | wc -l)
    log "Found ${suid_count} SUID binaries ✓"

    # Running services
    info "Extracting running services..."
    SERVICES_LIST=$(systemctl list-units --type=service --state=running --no-pager 2>/dev/null | \
        awk '/\.service/{print $1}' | sed 's/\.service//' | head -30)
    if [[ -z "$SERVICES_LIST" ]]; then
        SERVICES_LIST=$(ps aux 2>/dev/null | awk 'NR>1{print $11}' | sort -u | grep -v '^\[' | head -30)
    fi
    log "Found $(echo "$SERVICES_LIST" | grep -c '.') running services"

    # Open ports
    OPEN_PORTS=$(ss -tlnp 2>/dev/null || netstat -tlnp 2>/dev/null)
    log "Open ports extracted"

    # Sudo privileges (non-interactive check with timeout)
    SUDO_INFO=$(timeout 2 sudo -n -l 2>/dev/null)
    [[ -n "$SUDO_INFO" ]] && log "Sudo privileges found" || info "No passwordless sudo info available"

    # Cron jobs
    CRON_JOBS=$(crontab -l 2>/dev/null; ls -la /etc/cron* 2>/dev/null; cat /etc/crontab 2>/dev/null)

    # Docker check
    if [[ -f /.dockerenv ]] || grep -q docker /proc/1/cgroup 2>/dev/null; then
        SYS_INFO[container]="Docker"
        warn "Running inside Docker container"
    elif [[ -f /run/systemd/container ]]; then
        SYS_INFO[container]=$(cat /run/systemd/container)
        warn "Running inside ${SYS_INFO[container]} container"
    fi
}

#==============================================================================
# CVE SCANNER MODULE
#==============================================================================
declare -a CVE_RESULTS=()
CVE_JSON_ARRAY="[]"

query_cve_circl() {
    local vendor="$1" product="$2"
    local url="https://cve.circl.lu/api/search/${vendor}/${product}"
    local response
    response=$(curl -s --max-time 10 "$url" 2>/dev/null)
    if [[ $? -eq 0 ]] && echo "$response" | jq -e '.' &>/dev/null; then
        echo "$response" | jq -r '.[]? | select(.cvss != null) | "\(.id)|\(.cvss)|\(.summary // "N/A")"' 2>/dev/null | head -$MAX_CVE_RESULTS
    fi
}

query_nvd() {
    local keyword="$1"
    local encoded=$(echo "$keyword" | sed 's/ /%20/g')
    local url="https://services.nvd.nist.gov/rest/json/cves/2.0?keywordSearch=${encoded}&resultsPerPage=${MAX_CVE_RESULTS}"
    local response
    response=$(curl -s --max-time 15 "$url" 2>/dev/null)
    if [[ $? -eq 0 ]] && echo "$response" | jq -e '.vulnerabilities' &>/dev/null; then
        echo "$response" | jq -r '.vulnerabilities[]? |
            .cve as $c |
            ($c.metrics.cvssMetricV31[0]?.cvssData.baseScore // $c.metrics.cvssMetricV2[0]?.cvssData.baseScore // 0) as $score |
            "\($c.id)|\($score)|\($c.descriptions[0]?.value // "N/A")"' 2>/dev/null | head -$MAX_CVE_RESULTS
    fi
    sleep 1  # Rate limit for NVD
}

get_severity() {
    local score="$1"
    echo "$score" | awk '{
        if ($1+0 >= 9.0) print "CRITICAL"
        else if ($1+0 >= 7.0) print "HIGH"
        else if ($1+0 >= 4.0) print "MEDIUM"
        else if ($1+0 > 0) print "LOW"
        else print "INFO"
    }'
}

scan_component_cves() {
    local component="$1" version="$2" category="$3"
    local search_term="${component} ${version}"
    local results=""

    # Try CVE CircL first
    results=$(query_cve_circl "$component" "$component")

    # Fallback to NVD if no results
    if [[ -z "$results" ]]; then
        results=$(query_nvd "$search_term")
    fi

    if [[ -n "$results" ]]; then
        while IFS='|' read -r cve_id cvss desc; do
            [[ -z "$cve_id" ]] && continue
            local sev=$(get_severity "$cvss")
            # Count by severity
            case "$sev" in
                CRITICAL) ((TOTAL_CRITICAL++));;
                HIGH)     ((TOTAL_HIGH++));;
                MEDIUM)   ((TOTAL_MEDIUM++));;
                LOW)      ((TOTAL_LOW++));;
                *)        ((TOTAL_INFO++));;
            esac
            # Truncate description
            desc=$(echo "$desc" | cut -c1-200)
            CVE_RESULTS+=("${category}|${component}|${version}|${cve_id}|${cvss}|${sev}|${desc}")
            # Build JSON
            local entry=$(jq -n \
                --arg cat "$category" --arg comp "$component" --arg ver "$version" \
                --arg cve "$cve_id" --arg score "$cvss" --arg sev "$sev" --arg desc "$desc" \
                '{category:$cat,component:$comp,version:$ver,cve:$cve,cvss:($score|tonumber),severity:$sev,description:$desc}')
            CVE_JSON_ARRAY=$(echo "$CVE_JSON_ARRAY" | jq ". + [$entry]")
        done <<< "$results"
    fi
}

run_cve_scanner() {
    section "Advanced CVE Vulnerability Scanner"

    # 1. Kernel CVE scan
    info "Scanning kernel for CVEs..."
    local kver="${SYS_INFO[kernel]}"
    if [[ -n "$kver" ]]; then
        scan_component_cves "linux_kernel" "$kver" "Kernel"
        log "Kernel scan complete"
    fi

    # 2. Package CVE scan (top critical packages)
    info "Scanning installed packages for CVEs..."
    local critical_pkgs="openssl apache2 nginx php mysql postgresql sudo openssh docker containerd"
    for pkg in $critical_pkgs; do
        local pkg_ver=$(echo "$PACKAGES_LIST" | grep -i "^${pkg}=" | head -1 | cut -d= -f2 | cut -d- -f1 | cut -d: -f2)
        if [[ -n "$pkg_ver" ]]; then
            info "  Checking ${pkg} ${pkg_ver}..."
            scan_component_cves "$pkg" "$pkg_ver" "Package"
        fi
    done
    log "Package scan complete"

    # 3. Service CVE scan
    info "Scanning running services for CVEs..."
    for svc in $(echo "$SERVICES_LIST" | head -10); do
        local svc_name=$(basename "$svc" | sed 's/\.service//')
        local svc_ver=$($svc_name --version 2>/dev/null | grep -oP '\d+\.\d+[\.\d]*' | head -1)
        if [[ -n "$svc_ver" ]]; then
            info "  Checking ${svc_name} ${svc_ver}..."
            scan_component_cves "$svc_name" "$svc_ver" "Service"
        fi
    done
    log "Service scan complete"

    # 4. Sudo version check (binary check with timeout)
    local sudo_ver=$(timeout 2 sudo -n --version 2>/dev/null | head -1 | grep -oP '\d+\.\d+[\.\d]*')
    if [[ -n "$sudo_ver" ]]; then
        info "Checking sudo ${sudo_ver}..."
        scan_component_cves "sudo" "$sudo_ver" "Package"
    fi
}

#==============================================================================
# EXPLOIT SUGGESTION ENGINE
#==============================================================================
declare -a EXPLOITS=()

check_kernel_exploits() {
    section "Kernel Exploit Check"
    local kver="${SYS_INFO[kernel]}"
    local kmajor=$(echo "$kver" | cut -d. -f1)
    local kminor=$(echo "$kver" | cut -d. -f2)
    local kpatch=$(echo "$kver" | cut -d. -f3 | cut -d- -f1)

    # DirtyPipe - CVE-2022-0847 (5.8 <= kernel < 5.16.11, < 5.15.25, < 5.10.102)
    if [[ "$kmajor" -eq 5 ]] && [[ "$kminor" -ge 8 ]] && [[ "$kminor" -le 16 ]]; then
        EXPLOITS+=("CRITICAL|CVE-2022-0847|DirtyPipe|Kernel ${kver} may be vulnerable. Allows overwriting read-only files.|https://dirtypipe.cm4all.com/")
        warn "Potential DirtyPipe (CVE-2022-0847) vulnerability!"
    fi

    # DirtyCow - CVE-2016-5195 (kernel < 4.8.3)
    if [[ "$kmajor" -lt 4 ]] || ([[ "$kmajor" -eq 4 ]] && [[ "$kminor" -lt 9 ]]); then
        EXPLOITS+=("CRITICAL|CVE-2016-5195|DirtyCow|Kernel ${kver} may be vulnerable. Race condition in mm/cow.c.|https://dirtycow.ninja/")
        warn "Potential DirtyCow (CVE-2016-5195) vulnerability!"
    fi

    # PwnKit - CVE-2021-4034 (polkit pkexec)
    if command -v pkexec &>/dev/null; then
        local pk_ver=$(timeout 2 pkexec --version 2>/dev/null | grep -oP '\d+\.\d+' | head -1)
        EXPLOITS+=("HIGH|CVE-2021-4034|PwnKit|pkexec found (v${pk_ver}). Local privilege escalation via polkit.|https://github.com/berdav/CVE-2021-4034")
        warn "pkexec found - Check PwnKit (CVE-2021-4034)"
    fi

    # Baron Samedit - CVE-2021-3156 (sudo < 1.9.5p2)
    local sudo_ver=$(timeout 2 sudo -n --version 2>/dev/null | head -1 | grep -oP '\d+\.\d+\.\d+' | head -1)
    if [[ -n "$sudo_ver" ]]; then
        local s_major=$(echo "$sudo_ver" | cut -d. -f1)
        local s_minor=$(echo "$sudo_ver" | cut -d. -f2)
        if [[ "$s_major" -eq 1 ]] && [[ "$s_minor" -lt 9 ]]; then
            EXPLOITS+=("CRITICAL|CVE-2021-3156|Baron Samedit|sudo ${sudo_ver} is vulnerable. Heap buffer overflow.|https://blog.qualys.com/vulnerabilities-threat-research/2021/01/26/cve-2021-3156-heap-based-buffer-overflow-in-sudo-baron-samedit")
            warn "Potential Baron Samedit (CVE-2021-3156) in sudo ${sudo_ver}!"
        fi
    fi

    # GameOver(lay) - CVE-2023-2640 & CVE-2023-32629 (Ubuntu OverlayFS)
    if [[ "${SYS_INFO[distro_id]}" == "ubuntu" ]] && [[ "$kmajor" -eq 5 ]]; then
        EXPLOITS+=("HIGH|CVE-2023-2640|GameOver(lay)|Ubuntu kernel may have OverlayFS privilege escalation.|https://www.wiz.io/blog/ubuntu-overlayfs-vulnerability")
        warn "Check GameOver(lay) CVE-2023-2640 on Ubuntu"
    fi

    log "Kernel exploit check complete (${#EXPLOITS[@]} potential exploits)"
}

check_suid_exploits() {
    section "SUID/SGID Binary Analysis (GTFOBins)"
    local gtfo_bins="aria2c arp ash awk base32 base64 bash bridge busybox bzip2 cancel cat chmod chown column comm cp cpio cpulimit crash csh curl cut dash date dd dialog diff dig dmesg dmsetup docker dpkg ed emacs env eqn expand expect file find flock fmt fold ftp gawk gcc gdb genisoimage gimp git grep gtester gzip hd head hexdump highlight iconv iftop install ionice ip irb jjs join journalctl jq jrunscript ksh ksshell ld less look ltrace lua lwp-download lwp-request mail make man mawk more mount msgattrib msgcat msgconv msgfilter msgmerge msguniq mv mysql nano nasm nawk nc nice nl nmap node nohup npm octave od openssl openvpn paste pdb perl pg php pic pico pip pkexec pry python readelf red restic rev rlwrap rsync ruby run-mailcap run-parts rvim scp screen script sed service setarch sftp shuf socat sort sqlite3 ssh start-stop-daemon strace strings sysctl systemctl tac tail tar taskset tclsh tee telnet tftp time timeout tmux top ul unexpand uniq unshare vi vim vimdiff w3m wall watch wc wget whois wish xargs xdotool xmodmap xmore xxd xz yum zip zsh"

    while IFS= read -r suid_bin; do
        [[ -z "$suid_bin" ]] && continue
        local bin_name=$(basename "$suid_bin")
        if echo "$gtfo_bins" | grep -qw "$bin_name"; then
            EXPLOITS+=("HIGH|GTFOBins|SUID-${bin_name}|${suid_bin} has SUID bit and is listed in GTFOBins for privilege escalation.|https://gtfobins.github.io/gtfobins/${bin_name}/")
            warn "SUID exploit: ${suid_bin} → https://gtfobins.github.io/gtfobins/${bin_name}/"
        fi
    done <<< "$SUID_BINS"
}

check_misconfigurations() {
    section "Misconfiguration Detection"

    # World-writable /etc/passwd
    if [[ -w /etc/passwd ]]; then
        EXPLOITS+=("CRITICAL|MISCONFIG|Writable-passwd|/etc/passwd is world-writable! Can add root user.|N/A")
        warn "/etc/passwd is WRITABLE!"
    fi

    # World-writable /etc/shadow
    if [[ -r /etc/shadow ]]; then
        EXPLOITS+=("HIGH|MISCONFIG|Readable-shadow|/etc/shadow is readable by current user. Can crack hashes.|N/A")
        warn "/etc/shadow is READABLE!"
    fi

    # Docker socket
    if [[ -S /var/run/docker.sock ]] && [[ -w /var/run/docker.sock ]]; then
        EXPLOITS+=("CRITICAL|MISCONFIG|Docker-socket|Docker socket writable. Can escape to host as root.|N/A")
        warn "Docker socket is writable!"
    fi

    # Sudo NOPASSWD
    if echo "$SUDO_INFO" | grep -q "NOPASSWD"; then
        local nopasswd_cmds=$(echo "$SUDO_INFO" | grep "NOPASSWD" | head -5)
        EXPLOITS+=("HIGH|MISCONFIG|Sudo-NOPASSWD|Sudo without password: ${nopasswd_cmds}|N/A")
        warn "NOPASSWD sudo commands found!"
    fi

    # Writable cron directories
    for crondir in /etc/cron.d /etc/cron.daily /etc/cron.hourly /var/spool/cron; do
        if [[ -w "$crondir" ]]; then
            EXPLOITS+=("HIGH|MISCONFIG|Writable-cron|${crondir} is writable. Can plant cron backdoor.|N/A")
            warn "${crondir} is writable!"
        fi
    done

    # SSH keys readable
    if find /home -name "id_rsa" -readable 2>/dev/null | grep -q "."; then
        EXPLOITS+=("HIGH|MISCONFIG|SSH-keys|Private SSH keys found readable.|N/A")
        warn "Readable SSH private keys found!"
    fi

    # .env files with secrets
    local env_files=$(find / -name ".env" -readable 2>/dev/null -maxdepth 5 | head -5)
    if [[ -n "$env_files" ]]; then
        EXPLOITS+=("MEDIUM|MISCONFIG|Env-files|.env files found: ${env_files}|N/A")
        info "Readable .env files found"
    fi

    log "Misconfiguration check complete"
}

#==============================================================================
# REPORT GENERATOR
#==============================================================================
generate_report() {
    section "Generating Reports"

    # ---- TXT Report ----
    rpt "============================================================"
    rpt "  VULNSCAN VULNERABILITY REPORT"
    rpt "  Generated: $(date)"
    rpt "  Scanner Version: ${VERSION}"
    rpt "============================================================"
    rpt ""
    rpt "EXECUTIVE SUMMARY"
    rpt "─────────────────"
    rpt "  Critical : ${TOTAL_CRITICAL}"
    rpt "  High     : ${TOTAL_HIGH}"
    rpt "  Medium   : ${TOTAL_MEDIUM}"
    rpt "  Low      : ${TOTAL_LOW}"
    rpt "  Info     : ${TOTAL_INFO}"
    rpt "  Exploits : ${#EXPLOITS[@]}"
    rpt ""
    rpt "SYSTEM OVERVIEW"
    rpt "───────────────"
    rpt "  Hostname : ${SYS_INFO[hostname]}"
    rpt "  User     : ${SYS_INFO[user]}"
    rpt "  OS       : ${SYS_INFO[distro]}"
    rpt "  Kernel   : ${SYS_INFO[kernel_full]}"
    rpt "  Container: ${SYS_INFO[container]:-None detected}"
    rpt ""

    # CVE Findings
    rpt "CVE VULNERABILITIES"
    rpt "───────────────────"
    for entry in "${CVE_RESULTS[@]}"; do
        IFS='|' read -r cat comp ver cve cvss sev desc <<< "$entry"
        rpt "  [${sev}] ${cve} (CVSS: ${cvss})"
        rpt "    Component: ${comp} ${ver} (${cat})"
        rpt "    ${desc}"
        rpt ""
    done

    # Exploit Findings
    rpt "EXPLOIT VECTORS"
    rpt "───────────────"
    for entry in "${EXPLOITS[@]}"; do
        IFS='|' read -r sev cve name desc ref <<< "$entry"
        rpt "  [${sev}] ${cve} - ${name}"
        rpt "    ${desc}"
        rpt "    Reference: ${ref}"
        rpt ""
    done

    # ---- JSON Report ----
    local exploits_json="[]"
    for entry in "${EXPLOITS[@]}"; do
        IFS='|' read -r sev cve name desc ref <<< "$entry"
        local ej=$(jq -n --arg s "$sev" --arg c "$cve" --arg n "$name" --arg d "$desc" --arg r "$ref" \
            '{severity:$s,cve:$c,name:$n,description:$d,reference:$r}')
        exploits_json=$(echo "$exploits_json" | jq ". + [$ej]")
    done

    jq -n \
        --arg ts "$(date -Iseconds)" \
        --arg ver "$VERSION" \
        --arg host "${SYS_INFO[hostname]}" \
        --arg user "${SYS_INFO[user]}" \
        --arg os "${SYS_INFO[distro]}" \
        --arg kernel "${SYS_INFO[kernel]}" \
        --argjson crit "$TOTAL_CRITICAL" \
        --argjson high "$TOTAL_HIGH" \
        --argjson med "$TOTAL_MEDIUM" \
        --argjson low "$TOTAL_LOW" \
        --argjson cves "$CVE_JSON_ARRAY" \
        --argjson exploits "$exploits_json" \
        '{
            report: {
                timestamp: $ts,
                scanner_version: $ver,
                system: { hostname: $host, user: $user, os: $os, kernel: $kernel },
                summary: { critical: $crit, high: $high, medium: $med, low: $low },
                cve_findings: $cves,
                exploit_vectors: $exploits
            }
        }' > "$REPORT_JSON"

    log "TXT Report: ${REPORT_TXT}"
    log "JSON Report: ${REPORT_JSON}"
    log "LinPEAS Raw: ${LINPEAS_OUTPUT}"
}

print_summary() {
    section "SCAN COMPLETE - SUMMARY"
    echo ""
    echo -e "  ${R}╔═══════════════════════════════════════╗${NC}"
    echo -e "  ${R}║  VULNERABILITY SUMMARY                ║${NC}"
    echo -e "  ${R}╠═══════════════════════════════════════╣${NC}"
    printf "  ${R}║${NC}  ${R}Critical : %-5s${NC}                    ${R}║${NC}\n" "$TOTAL_CRITICAL"
    printf "  ${R}║${NC}  ${Y}High     : %-5s${NC}                    ${R}║${NC}\n" "$TOTAL_HIGH"
    printf "  ${R}║${NC}  ${M}Medium   : %-5s${NC}                    ${R}║${NC}\n" "$TOTAL_MEDIUM"
    printf "  ${R}║${NC}  ${B}Low      : %-5s${NC}                    ${R}║${NC}\n" "$TOTAL_LOW"
    printf "  ${R}║${NC}  ${C}Exploits : %-5s${NC}                    ${R}║${NC}\n" "${#EXPLOITS[@]}"
    echo -e "  ${R}╚═══════════════════════════════════════╝${NC}"
    echo ""

    if [[ ${#EXPLOITS[@]} -gt 0 ]]; then
        echo -e "  ${R}TOP EXPLOIT VECTORS:${NC}"
        local count=0
        for entry in "${EXPLOITS[@]}"; do
            IFS='|' read -r sev cve name desc ref <<< "$entry"
            local color="$NC"
            [[ "$sev" == "CRITICAL" ]] && color="$R"
            [[ "$sev" == "HIGH" ]] && color="$Y"
            echo -e "  ${color}[${sev}]${NC} ${cve} - ${W}${name}${NC}"
            echo -e "        ${D}${desc}${NC}"
            [[ "$ref" != "N/A" ]] && echo -e "        ${C}→ ${ref}${NC}"
            ((count++))
            [[ $count -ge 15 ]] && break
        done
    fi
    echo ""
    echo -e "  ${G}Reports saved to: ${W}${OUTPUT_DIR}/${NC}"
    echo ""
}

#==============================================================================
# MAIN
#==============================================================================
main() {
    banner
    disclaimer
    check_deps
    run_linpeas
    parse_system_info
    run_cve_scanner
    check_kernel_exploits
    check_suid_exploits
    check_misconfigurations
    generate_report
    print_summary
}

# Handle arguments
case "${1:-}" in
    --skip-linpeas)
        # Use existing linpeas output
        if [[ -n "$2" ]] && [[ -f "$2" ]]; then
            banner
            check_deps
            LINPEAS_OUTPUT="$2"
            cp "$2" "${OUTPUT_DIR}/linpeas_raw.txt"
            info "Using existing LinPEAS output: $2"
            parse_system_info
            run_cve_scanner
            check_kernel_exploits
            check_suid_exploits
            check_misconfigurations
            generate_report
            print_summary
        else
            err "Usage: $0 --skip-linpeas <linpeas_output_file>"
            exit 1
        fi
        ;;
    --help|-h)
        banner
        echo "Usage: $0 [OPTIONS]"
        echo ""
        echo "Options:"
        echo "  (no args)                    Run full scan (LinPEAS + CVE lookup)"
        echo "  --skip-linpeas <file>        Skip LinPEAS, use existing output file"
        echo "  --help, -h                   Show this help"
        echo ""
        echo "Environment Variables:"
        echo "  CVSS_THRESHOLD=5.0           Minimum CVSS score to report (default: 5.0)"
        echo "  MAX_CVE_RESULTS=10           Max CVEs per component (default: 10)"
        echo ""
        echo "Examples:"
        echo "  ./vulnscan.sh                                         # Full scan"
        echo "  ./vulnscan.sh --skip-linpeas ./linpeas_out.txt        # Reuse output"
        echo "  CVSS_THRESHOLD=7.0 ./vulnscan.sh                      # Only high/crit"
        ;;
    *)
        main
        ;;
esac

# Stop execution here — everything below is embedded data, not code
exit 0

